// All people, channels, campaigns and messages below are fictional.
// Expected labels describe the prototype's evidence rubric, not a legal finding.

const makeCampaign = (id, title, organizer, platform, expectedRisk, rows, status = 'new') => ({
  id,
  title,
  organizer,
  platform,
  status,
  synthetic: true,
  expectedRisk,
  sources: rows.map((row, index) => {
    const item = typeof row === 'string' ? { text: row } : row;
    const hour = String(10 + index).padStart(2, '0');
    return {
      id: `${id}-s${index + 1}`,
      type: item.type || 'text',
      text: item.text,
      author: organizer,
      url: `https://example.com/synthetic/${id}/post-${index + 1}`,
      timestamp: `2026-10-20T${hour}:15:00+05:00`,
      date: `20 окт · ${hour}:15`,
      campaignRef: id,
      ...(item.image ? { image: item.image } : {}),
    };
  }),
});

